function render(key, lang) {
  const page = pages[key], t = page.text[lang], ui = languages[lang];
  const steps = key === 'ideas'
    ? ideaSteps[lang]
    : key === 'gift'
      ? giftSteps[lang]
      : key === 'letter'
        ? letterSteps[lang]
        : ['everything','distance','adultLetter'].includes(key)
          ? t.steps.map((title,i) => ({ title, detail: t.faq[i]?.[1] || ui.guide }))
          : t.steps.map(title => ({ title, detail: ui.guide }));
  const alternates = Object.keys(languages).map(l => `<link rel="alternate" hreflang="${l}" href="${urlFor(key,l)}">`).join('') + `<link rel="alternate" hreflang="x-default" href="${urlFor(key,'en')}">`;
  const faqs = t.faq.map(([q,a]) => `<details><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join('');
  const related = Object.keys(pages).filter(k=>k!==key).map(k=>`<a class="related" href="/${lang}/${pages[k].slugs[lang]}"><span>${pages[k].icon}</span>${esc(pages[k].text[lang].h1.split(':')[0])}</a>`).join('');
  const langLinks = Object.keys(languages).map(l=>`<a lang="${l}" hreflang="${l}" href="/${l}/${page.slugs[l]}">${l.toUpperCase()}</a>`).join('');
  const target = `/?lang=${lang}#${page.action}`;
  const priceData = page.product ? ` data-seo-price="${page.product}"` : '';
  const priceScript = page.product ? `<script>(()=>{const product=${JSON.stringify(page.product)},markets={FR:['eur','fr-FR',900],US:['usd','en-US',900],GB:['gbp','en-GB',700],AU:['aud','en-AU',1500],CA:['cad','en-CA',1300],ES:['eur','es-ES',900],DE:['eur','de-DE',900],BR:['brl','pt-BR',4900],PT:['eur','pt-PT',900]},prices={'magic-letter':{eur:199,usd:199,gbp:169,aud:299,cad:299,brl:1190},'santa-surprise':{eur:2900,usd:3200,gbp:2500,aud:4900,cad:4300,brl:17900},'big-christmas-box':{eur:6900,usd:7500,gbp:5900,aud:10900,cad:9900,brl:42900}};function show(market){const m=markets[market]||markets.FR,p=prices[product][m[0]],money=v=>new Intl.NumberFormat(m[1],{style:'currency',currency:m[0].toUpperCase()}).format(v/100).replace(m[0]==='aud'?'$':'__','A$').replace(m[0]==='cad'?'$':'__','CA$');let value=${JSON.stringify(ui.from)}+' '+money(p);if(product!=='magic-letter')value=money(p)+' + '+money(m[2])+' '+${JSON.stringify(ui.shipping)};document.querySelectorAll('[data-seo-price]').forEach(el=>el.textContent=value)}const saved=localStorage.getItem('noelwish_market');if(saved)show(saved);else fetch('/api/visitor-context').then(r=>r.json()).then(d=>show(d.market)).catch(()=>show('${lang==='en'?'US':lang==='es'?'ES':lang==='pt'?'PT':lang==='de'?'DE':'FR'}'))})();</script>` : '';
  const graph = [
    {'@type':'Organization','@id':`${origin}/#organization`,name:'NoelWish',url:`${origin}/`,email:'magic@noelwish.com'},
    {'@type':'WebSite','@id':`${origin}/#website`,url:`${origin}/`,name:'NoelWish',publisher:{'@id':`${origin}/#organization`},inLanguage:Object.keys(languages)},
    {'@type':'WebPage','@id':urlFor(key,lang),url:urlFor(key,lang),name:t.title,description:t.description,inLanguage:lang,isPartOf:{'@id':`${origin}/#website`},breadcrumb:{'@id':`${urlFor(key,lang)}#breadcrumb`}},
    {'@type':'BreadcrumbList','@id':`${urlFor(key,lang)}#breadcrumb`,itemListElement:[{'@type':'ListItem',position:1,name:ui.home,item:`${origin}/?lang=${lang}`},{'@type':'ListItem',position:2,name:t.h1,item:urlFor(key,lang)}]},
    {'@type':'FAQPage',mainEntity:t.faq.map(([q,a])=>({'@type':'Question',name:q,acceptedAnswer:{'@type':'Answer',text:a}}))}
  ];
  const productPrices = {'magic-letter':'1.99','santa-surprise':'29.00','big-christmas-box':'69.00'};
  const marketCountry = {fr:'FR',en:'US',es:'ES',pt:'PT',de:'DE'}[lang];
  if (page.product) {
    const isDigital = page.product === 'magic-letter';
    graph.push({
      '@type':'Product',
      name:t.h1,
      description:t.description,
      image:`${origin}${page.image}`,
      brand:{'@type':'Brand',name:'NoelWish'},
      offers:{
        '@type':'Offer',
        url:urlFor(key,lang),
        priceCurrency:'EUR',
        price:productPrices[page.product],
        availability:'https://schema.org/InStock',
        shippingDetails:{
          '@type':'OfferShippingDetails',
          shippingDestination:{'@type':'DefinedRegion',addressCountry:marketCountry},
          shippingRate:{'@type':'MonetaryAmount',value:isDigital?'0.00':'9.00',currency:'EUR'},
          deliveryTime:{
            '@type':'ShippingDeliveryTime',
            handlingTime:{'@type':'QuantitativeValue',minValue:0,maxValue:isDigital?0:7,unitCode:'DAY'},
            transitTime:{'@type':'QuantitativeValue',minValue:isDigital?0:3,maxValue:isDigital?0:7,unitCode:'DAY'}
          }
        },
        hasMerchantReturnPolicy:{
          '@type':'MerchantReturnPolicy',
          applicableCountry:marketCountry,
          returnPolicyCategory:'https://schema.org/MerchantReturnNotPermitted'
        }
      }
    });
  }
  const schema = {'@context':'https://schema.org','@graph':graph};
  return `<!doctype html><html lang="${lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#690b16"><title>${esc(t.title)}</title><meta name="description" content="${esc(t.description)}"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="${urlFor(key,lang)}">${alternates}<meta property="og:type" content="website"><meta property="og:site_name" content="NoelWish"><meta property="og:title" content="${esc(t.title)}"><meta property="og:description" content="${esc(t.description)}"><meta property="og:url" content="${urlFor(key,lang)}"><meta property="og:image" content="${origin}${page.image}"><meta name="twitter:card" content="summary_large_image"><script type="application/ld+json">${JSON.stringify(schema).replace(/</g,'\\u003c')}</script><style>
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Playfair+Display:wght@600;700&display=swap');
:root{--gold:#f6d37b;--cream:#fffaf3;--muted:#f3dfe1;--red:#861321;--dark:#4d0610}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:var(--cream);font-family:'DM Sans',sans-serif;background:radial-gradient(circle at 50% 0,#d88b4030,transparent 34%),linear-gradient(145deg,var(--dark),var(--red) 55%,#b32230);min-height:100vh}a{color:inherit;text-decoration:none}.snow{position:fixed;inset:0;pointer-events:none;opacity:.35;background-image:radial-gradient(2px 2px at 40px 90px,#fff,transparent),radial-gradient(2px 2px at 160px 50px,#fff,transparent),radial-gradient(1px 1px at 100px 150px,#fff,transparent);background-size:210px 210px;z-index:-1}header{min-height:76px;padding:16px clamp(18px,5vw,72px);display:flex;align-items:center;justify-content:space-between;gap:20px;border-bottom:1px solid #ffd98a45;background:#610a16df;backdrop-filter:blur(12px)}.brand{font:700 28px 'Playfair Display',serif;color:var(--gold)}nav,.langs{display:flex;gap:16px;align-items:center;flex-wrap:wrap}nav a,.langs a{font-size:13px;color:#fffddd}.langs{gap:7px}.langs a{border:1px solid #f6d37b55;border-radius:20px;padding:6px 8px}.hero{max-width:1160px;margin:auto;padding:78px 24px 60px;display:grid;grid-template-columns:1.25fr .75fr;gap:56px;align-items:center}.eyebrow{text-transform:uppercase;color:var(--gold);font-weight:800;letter-spacing:3px;font-size:12px}h1,h2,h3{font-family:'Playfair Display',serif}h1{font-size:clamp(42px,6vw,72px);line-height:1.06;margin:18px 0 22px}h2{font-size:clamp(30px,4vw,45px);margin:0 0 28px}.lead{font-size:18px;line-height:1.75;color:var(--muted);max-width:700px}.price{margin:20px 0;color:var(--gold);font-weight:700}.btn{display:inline-flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#ffe29a,#eebd55);color:#5b1018;border-radius:999px;padding:16px 25px;font-weight:800;box-shadow:0 12px 32px #0003}.visual{position:relative;display:grid;place-items:center;min-height:390px}.visual:before{content:'';position:absolute;width:330px;height:330px;border-radius:50%;background:#f6d37b19;border:1px solid #f6d37b45}.visual img{position:relative;width:min(360px,100%);height:390px;object-fit:contain;filter:drop-shadow(0 20px 24px #26000688)}.visual .icon{position:absolute;right:8%;top:7%;font-size:64px;filter:drop-shadow(0 8px 12px #0005)}section{max-width:1120px;margin:auto;padding:70px 24px}.cream{max-width:none;background:#fffaf3;color:#4c1720}.cream>div{max-width:1120px;margin:auto}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.card{border-radius:22px;padding:28px;background:#fff;border:1px solid #d6b56f;color:#551722;box-shadow:0 12px 35px #3d000e12}.card .num{display:grid;place-items:center;width:44px;height:44px;border-radius:50%;background:#8c1523;color:#fff;font-weight:800}.card h3{font-size:22px}.card p{line-height:1.65;color:#76535a}.benefit{background:#ffffff10;border:1px solid #f6d37b45;border-radius:20px;padding:26px;text-align:center;font-weight:700}.benefit span{display:block;font-size:38px;margin-bottom:12px}.faq{max-width:850px}details{border-bottom:1px solid #8c152333;padding:18px 0}summary{font-weight:800;cursor:pointer;color:#6b101b}details p{line-height:1.7;color:#6e4b52}.related-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.related{border:1px solid #f6d37b55;border-radius:17px;padding:18px;text-align:center;background:#ffffff0c;font-weight:700}.related span{display:block;font-size:30px;margin-bottom:8px}.final{text-align:center}.final p{color:var(--muted)}footer{text-align:center;padding:35px 20px;border-top:1px solid #ffffff24;color:#dac9ca;font-size:13px}@media(max-width:800px){header{align-items:flex-start;flex-direction:column}nav{display:none}.hero{grid-template-columns:1fr;text-align:center;padding-top:48px}.lead{margin-left:auto;margin-right:auto}.visual{min-height:270px}.visual:before{width:240px;height:240px}.visual img{height:290px}.grid{grid-template-columns:1fr}.related-grid{grid-template-columns:1fr 1fr}section{padding:50px 18px}}@media(max-width:480px){.related-grid{grid-template-columns:1fr}.langs{width:100%;justify-content:center}h1{font-size:39px}}
</style></head><body><div class="snow"></div><header><a class="brand" href="/?lang=${lang}">✦ NoelWish</a><nav><a href="/?lang=${lang}">${ui.home}</a><a href="/?lang=${lang}#gifts">${ui.gifts}</a><a href="/?lang=${lang}#wall">${ui.wall}</a></nav><div class="langs">${langLinks}</div></header><main><div class="hero"><div><div class="eyebrow">${esc(t.eyebrow)}</div><h1>${esc(t.h1)}</h1><p class="lead">${esc(t.lead)}</p><p class="price"${priceData}>${esc(t.price)}</p><a class="btn" href="${target}">${esc(t.cta)} →</a></div><div class="visual"><img src="${page.image}" alt="NoelWish Santa Claus"><span class="icon">${page.icon}</span></div></div><section class="cream"><div><h2>${esc(ui.how)}</h2><div class="grid">${steps.map((s,i)=>`<article class="card"><span class="num">${i+1}</span><h3>${esc(s.title)}</h3><p>${esc(s.detail)}</p></article>`).join('')}</div></div></section><section><h2>${esc(ui.benefits)}</h2><div class="grid">${t.benefits.map((b,i)=>`<div class="benefit"><span>${['✨','🎅','❤️'][i]}</span>${esc(b)}</div>`).join('')}</div></section><section class="cream"><div class="faq"><h2>${esc(ui.faq)}</h2>${faqs}</div></section><section><h2>${esc(ui.related)}</h2><div class="related-grid">${related}</div></section><section class="final"><h2>${esc(t.h1)}</h2><p${priceData}>${esc(t.price)}</p><a class="btn" href="${target}">${esc(t.cta)} →</a></section></main><footer>✦ NoelWish — ${esc(ui.footer)} · <a href="/mentions-legales?lang=${lang}">Legal</a> · <a href="/confidentialite?lang=${lang}">Privacy</a></footer>${priceScript}</body></html>`;
}

for (const [key,page] of Object.entries(pages)) {
  for (const lang of Object.keys(languages)) {
    const dir = path.join(root,lang);
    fs.mkdirSync(dir,{recursive:true});
    const analyticsMarkup = `<script defer src="/_vercel/insights/script.js"></script><script src="/nw-events.js"></script>`;
    const trackedHtml = render(key,lang)
      .replace('</style></head><body>', `</style>${analyticsMarkup}</head><body data-product="${page.product || key}">`)
      .replaceAll(`<a class="btn" href="/?lang=${lang}#${page.action}">`, `<a class="btn" href="/?lang=${lang}#${page.action}" data-product="${page.product || key}" data-analytics-label="seo_cta">`);
    fs.writeFileSync(path.join(dir,`${page.slugs[lang]}.html`),trackedHtml);
  }
}

const entries = [`  <url><loc>${origin}/</loc><lastmod>2026-11-04</lastmod><changefreq>weekly</changefreq><priority>1.0</priority></url>`];
for (const [key,page] of Object.entries(pages)) {
  for (const lang of Object.keys(languages)) {
    const links = Object.keys(languages).map(l=>`<xhtml:link rel="alternate" hreflang="${l}" href="${urlFor(key,l)}" />`).join('');
    entries.push(`  <url><loc>${urlFor(key,lang)}</loc><lastmod>2026-11-04</lastmod><changefreq>weekly</changefreq><priority>${key === 'ideas' ? '0.7' : '0.8'}</priority>${links}<xhtml:link rel="alternate" hreflang="x-default" href="${urlFor(key,'en')}" /></url>`);
  }
}
for (const slug of ['cgv','mentions-legales','confidentialite']) entries.push(`  <url><loc>${origin}/${slug}</loc><lastmod>2026-11-04</lastmod><priority>0.2</priority></url>`);
fs.writeFileSync(path.join(root,'sitemap.xml'),`<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">\n${entries.join('\n')}\n</urlset>\n`);
console.log(`Generated ${Object.keys(pages).length * Object.keys(languages).length} localized SEO pages and sitemap.xml`);
